// Little Clawbot. Assets are generated by scripts/build_brand_assets.py.
// Keep the existing component exports so callers retain their layout API.
import type { CSSProperties } from "react";
import mascot from "./assets/little-clawbot.svg";
import compactMascot from "./assets/little-clawbot-compact.svg";

export type Mood = "calm" | "happy" | "wink" | "worried";
export type Tool = "wrench" | "magnifier" | "clipboard" | null;

interface ClawbertProps {
  size?: number;
  mood?: Mood;
  tool?: Tool;
  color?: string;
  shadow?: string;
  style?: CSSProperties;
}

export function Clawbert({ size = 120, style }: ClawbertProps) {
  return <img src={mascot} width={size} height={size} style={style} alt="" aria-hidden="true" />;
}

interface ClawMarkProps {
  size?: number;
  color?: string;
}

export function ClawMark({ size = 32 }: ClawMarkProps) {
  return <img src={compactMascot} width={size} height={size} alt="" aria-hidden="true" />;
}

// Wordmark — Little Clawbot next to the word "clawmetry".
interface WordmarkProps {
  size?: number;
  color?: string;
  mark?: string;
}
export function Wordmark({
  size = 1,
  color = "var(--ink)",
  mark = "var(--claw-red)",
}: WordmarkProps) {
  return (
    <div
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 8 * size,
        fontFamily: "var(--f-display)",
        fontSize: 28 * size,
        color,
        letterSpacing: "-0.01em",
        lineHeight: 1,
      }}
    >
      <ClawMark size={28 * size} color={mark} />
      <span>ClawMetry</span>
    </div>
  );
}
